/// @file device_registry.cpp
/// @brief Wiring for the auto-generated RemoteTerminal.
/// @details Auto-generated by Exhibition. Instantiates each device
///          handler with its HAL handle/pin/channel and registers it
///          with the RemoteTerminal. Regenerated on every run; edit the
///          .ioc and rerun rather than hand-editing this file.

#include "rt/device_registry.h"

#include "main.h"
#include "adc.h"
#include "can.h"
#include "i2c.h"
#include "rtc.h"
#include "spi.h"
#include "usart.h"
#include "rt/communication/scheduler.h"
#include "rt/system/system_handler.h"
#include "rt/sub_addresses.h"
#include "rt/service_hashes.h"
#include "rt/transports/sys_tick_clock.h"
#include "rt/transports/uart_frame_transport.h"
#include "rt/devices/adc_handler.h"
#include "rt/devices/can_handler.h"
#include "rt/devices/gpio_input_handler.h"
#include "rt/devices/gpio_output_handler.h"
#include "rt/devices/i2c_handler.h"
#include "rt/devices/rtc_handler.h"
#include "rt/devices/spi_handler.h"

static UartFrameTransport g_transport(&huart2);
static SysTickClock g_clock;
static FaultCounter g_fault_counter;
static OffsetSmoother g_offset_smoother;
static SystemHandler g_system_handler(10, g_clock, g_fault_counter, g_offset_smoother);

static AdcHandler g_adc_hadc1_ch1(&hadc1, 1, g_clock);
static CanHandler g_can_hcan1(&hcan1, g_clock);
static GpioInputBankHandler g_gpio_in_bank_B(GPIOB, 0x0004, g_clock);
static GpioInputBankHandler g_gpio_in_bank_D(GPIOD, 0x0020, g_clock);
static GpioOutputBankHandler g_gpio_out_bank_C(GPIOC, 0x0001, g_clock);
static GpioOutputBankHandler g_gpio_out_bank_D(GPIOD, 0xF010, g_clock);
static GpioOutputBankHandler g_gpio_out_bank_E(GPIOE, 0x0008, g_clock);
static I2cHandler g_i2c_hi2c1(&hi2c1, g_clock);
static RtcHandler g_rtc(&hrtc);
static SpiHandler g_spi_hspi1(&hspi1, g_clock);

static RemoteTerminal g_rt(g_transport, g_clock, g_fault_counter);

void init_rt()
{
    // Refresh SystemCoreClock from the live PLL config before latching the
    // SysTick reload: the file-scope clock ctor ran pre-PLL (16 MHz default).
    SystemCoreClockUpdate();
    g_clock.sync_from_core_clock();
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::System), &g_system_handler, kServiceHashSystem);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::AdcHadc1Ch1), &g_adc_hadc1_ch1, kServiceHashAdc);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::CanHcan1), &g_can_hcan1, kServiceHashCan);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::GpioInBankB), &g_gpio_in_bank_B, kServiceHashGpioIn);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::GpioInBankD), &g_gpio_in_bank_D, kServiceHashGpioIn);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::GpioOutBankC), &g_gpio_out_bank_C, kServiceHashGpioOut);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::GpioOutBankD), &g_gpio_out_bank_D, kServiceHashGpioOut);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::GpioOutBankE), &g_gpio_out_bank_E, kServiceHashGpioOut);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::I2cHi2c1), &g_i2c_hi2c1, kServiceHashI2c);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::Rtc), &g_rtc, kServiceHashRtc);
    g_rt.register_handler(static_cast<uint8_t>(SubAddress::SpiHspi1), &g_spi_hspi1, kServiceHashSpi);
}

void tick_rt()
{
    g_rt.tick();
    if (g_system_handler.reset_pending()) {
        HAL_Delay(10);
        HAL_NVIC_SystemReset();
    }
}
